const cases={label:{name:'AcrossB Label Helper',short:'Label preparation',ball:'Batch details',titles:['Make label preparation easier to hand off.','Reduce repeated typing. Keep people in control.','Fewer entry errors. Easier handoffs.'],copy:['Experienced managers repeatedly typed batch details into a label worksheet. Each transfer created another chance for an error.','The helper reads selected batches, prepares the inputs, and enters them into the worksheet through browser controls. An associate still checks the completed label.','Sung reports fewer data-entry mistakes and easier delegation to frontline associates, including Spanish-speaking staff.'],decision:['The same details. Re-entered by hand.','Automate the repetition. Keep the final review.','~90% fewer data-entry errors.'],boundary:['Illustrative batch: DEMO-042 · SKU DEMO-A · 12 units.','Browser input, not a Sheets API. Final saved values are not independently verified by the helper.','Review the completed label before printing.'],foot:'User-reported operational observation. Reduction calculated as 86.7%–93.3%; not independently audited. Measurement period and methodology unverified. Error counts are not counts of distinct affected batches.',source:'acrossb-label-helper'},qr:{name:'AcrossB Flow QR Helper',short:'Batch identification',ball:'Batch identifier',titles:['Find the right batch before taking the next step.','Validate before selecting.','Less searching. The checks stay.'],copy:['Staff searched for batch numbers and checked the work record manually. The task needed speed—and care.','Parse the identifier, check the complete and stable list, and require one exact match. Dry run comes first; selection requires deliberate live mode.','Historical owner report: broader daily preparation for approximately 150 batches took about 20–30 minutes with the tools versus nearly 50 minutes manually. This is not a QR-only result.'],decision:['Find the batch. Verify the record.','Make matching faster without guessing.','Broader workflow context, not a QR-only benchmark.'],boundary:['Fictional rows can share a month, day and batch number across different years.','The helper selects a row. It does not complete the job.','Validation before selection remains part of the workflow.'],foot:'Historical owner-reported broader workflow comparison; measurement period and methodology unverified. Not attributable to QR Helper alone. Quantity reconciliation and final completion remain manual.',source:'acrossb-flow-qr-helper'}};
const requestedCase=new URLSearchParams(location.search).get('case');
const stageNames=['Spot the Friction','Design the Play','Measure the Impact'];let currentCase='label',stage=0;
const byId=id=>document.getElementById(id);
function marker(n,label,x,y,person=false){return `<g><circle class="node ${person?'person':''}" cx="${x}" cy="${y}" r="3.9"/><text class="node-number ${person?'person-number':''}" x="${x}" y="${y}">${n}</text><text class="node-label" x="${x}" y="${y+7.3}">${label}</text></g>`}
function ball(x,y){return `<g aria-hidden="true"><circle class="ball" cx="${x}" cy="${y}" r="1.9"/><path class="ball-line" d="M${x-1.9},${y}h3.8 M${x},${y-1.9}v3.8 M${x-1.4},${y-1.3}q2.8,1.3,0,2.6"/></g>`}
function court(mobile){const w=mobile?60:100,h=mobile?86:60;const isLabel=currentCase==='label',after=stage>0;let nodes,routes,extra='',bp;
if(isLabel){nodes=mobile?(after?[[1,'Batch data',15,14],[4,'Helper',30,34],[3,'Worksheet',30,56],[2,'Human review',43,73,true]]:[[1,'Batch data',15,14],[2,'Manual entry',30,39,true],[3,'Worksheet',43,65]]):(after?[[1,'Batch data',13,27],[4,'Helper',43,27],[3,'Worksheet',78,27],[2,'Human review',78,46,true]]:[[1,'Batch data',14,29],[2,'Manual entry',48,29,true],[3,'Worksheet',83,29]]);routes=mobile?(after?'M17,18 L28,30 M30,39 L30,51 M33,60 L40,69':'M17,18 L28,34 M32,44 L41,60'):(after?'M18,27 L38,27 M48,27 L73,27 M78,32 L78,41':'M19,29 L43,29 M53,29 L78,29');bp=after?(mobile?[41,68]:[78,39]):(mobile?[19,20]:[22,29]);}
else{nodes=mobile?(after?[[1,'QR identifier',15,12],[4,'Parser',22,30],[5,'Validation',39,47],[3,'Work row',43,68],[2,'Staff',15,68,true]]:[[1,'Identifier',15,14],[2,'Staff',20,39,true],[3,'Work rows',42,63]]):(after?[[1,'Identifier',11,25],[4,'Parser',34,25],[5,'Validation',59,25],[3,'Work row',85,25],[2,'Staff',62,46,true]]:[[1,'Identifier',13,26],[2,'Staff',44,40,true],[3,'Work rows',82,26]]);routes=mobile?(after?'M17,16 L21,25 M25,34 L36,43 M40,52 L42,63':'M17,18 L19,34 M24,42 Q43,36 42,58'):(after?'M16,25 L29,25 M39,25 L54,25 M64,25 L80,25':'M18,27 L40,37 M49,38 Q66,42 78,29');bp=after?(mobile?[37,42]:[55,25]):(mobile?[25,43]:[52,38]);if(after)extra=mobile?'<text class="small-label" x="6" y="80">Dry run: no row selected</text>':'<text class="small-label" x="35" y="55">Dry run: no row selected</text>';}
const description=isLabel?(after?'Selected batch details pass through the helper into the worksheet, then to an associate for final review.':'Batch data is manually re-entered by a person into the worksheet.'):(after?'The QR identifier passes through parsing and validation. One exact match is required. In dry run, no checkbox is selected.':'Staff search displayed work rows and verify the identifier.');
return `<svg class="court ${mobile?'mobile-court':'desktop-court'}" viewBox="0 0 ${w} ${h}" role="img" aria-label="${description}"><defs><marker id="arrow-${mobile}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0 0 L10 5 L0 10" fill="none" stroke="#795891" stroke-width="1.5"/></marker></defs><rect class="court-line" x="3" y="3" width="${w-6}" height="${h-6}" rx="2"/><path class="court-line" d="M3 ${h/2}H${w-3}"/><circle class="court-line" cx="${w/2}" cy="${h/2}" r="9"/><path class="court-line" d="M${w/2-10} 3v10h20V3 M${w/2-10} ${h-3}v-10h20v10"/><circle class="court-line" cx="${w/2}" cy="8" r="1.5"/><circle class="court-line" cx="${w/2}" cy="${h-8}" r="1.5"/><path class="route ${after?'':'manual'}" d="${routes}" marker-end="url(#arrow-${mobile})"/>${nodes.map(n=>marker(...n)).join('')}${ball(...bp)}${extra}</svg>`}
function impact(){const a=currentCase==='label';return `<div class="metric-board"><span class="metric-label">${a?'BATCH DATA ENTRY ERRORS':'BROADER DAILY PREPARATION — OWNER REPORT'}</span><div class="metric-values"><div><small>BEFORE</small><strong>${a?'~15':'~50'}${a?'':'<small>MIN</small>'}</strong></div><span>→</span><div><small>AFTER</small><strong>${a?'1–2':'~20–30'}${a?'':'<small>MIN</small>'}</strong></div></div><p class="metric-sub">${a?'Errors per approximately 150 batches':'Approximately 150 batches per day'}</p><p class="metric-note">${a?'Human review retained':'Validation before selection'}</p></div>`}
function render(){const c=cases[currentCase];document.title=`${c.name} · ${stageNames[stage]} · The Playbook`;byId('stage-label').textContent=`${c.name} / ${stageNames[stage]}`;byId('story-title').textContent=c.titles[stage];byId('story-copy').textContent=c.copy[stage];byId('decision').textContent=c.decision[stage];byId('boundary').textContent=c.boundary[stage];byId('board-case').textContent=c.short;byId('ball-meaning').textContent=c.ball;byId('board').innerHTML=stage===2?impact():court(false)+court(true);const roles=currentCase==='label'?(stage?['Batch data','Human review','Worksheet','Label Helper']:['Batch data','Manual entry','Worksheet']):(stage?['QR identifier','Staff authorization','Work row','QR parser','Validation']:['Identifier','Staff','Work rows']);byId('legend').innerHTML=roles.map((r,i)=>`<span><b>${i+1}</b>${r}</span>`).join('');byId('guard').innerHTML=currentCase==='qr'&&stage===1?'<div class="guard"><span class="guard-symbol" aria-hidden="true">⊘</span><div><strong>More than one match? Stop.</strong>Two fictional rows share the same identifier. Nothing is selected. Review the list.</div></div>':currentCase==='label'&&stage===1?'<div class="static-check"><b>Human review</b> · Check the completed label before printing.</div>':'';byId('evidence').innerHTML=stage===2?`<p class="metric-footnote">${c.foot}</p>`:'';byId('transcript').innerHTML=`<p>${currentCase==='label'?'Selected batch details → helper → worksheet → human review. The helper uses browser input, not the Google Sheets API. It does not independently verify final saved labels. The public configurable edition has not been independently validated in a live warehouse.':'QR identifier → parser → complete and stable list check → exactly one match → dry-run preview → deliberate live selection. Ambiguous matches stop the flow. The helper does not submit or complete work. Repository reports describe fake-DOM tests, not production or physical-scanner validation.'}</p><p>${c.foot}</p><p>All illustrated data is fictional. These tools are independent; this page does not connect to either tool or any live account.</p><a href="https://github.com/SungJung0616/${c.source}" rel="noreferrer">Read the public source</a>`;byId('previous').disabled=stage===0;byId('next').disabled=stage===2;byId('step-count').textContent=`${stage+1} of 3 · Static view`;document.querySelectorAll('[data-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.case===currentCase)));document.querySelectorAll('[data-stage]').forEach(b=>{if(Number(b.dataset.stage)===stage)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current')});const u=new URL(location);u.searchParams.set('case',currentCase);u.searchParams.set('stage',stage);history.replaceState(null,'',u);}
document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>{currentCase=b.dataset.case;stage=0;render()}));document.querySelectorAll('[data-stage]').forEach(b=>b.addEventListener('click',()=>{stage=Number(b.dataset.stage);render()}));byId('previous').addEventListener('click',()=>{stage=Math.max(0,stage-1);render()});byId('next').addEventListener('click',()=>{stage=Math.min(2,stage+1);render()});const params=new URLSearchParams(location.search);if(params.get('case')==='qr')currentCase='qr';stage=Math.max(0,Math.min(2,Number(params.get('stage'))||0));render();
